// DRAFT ONLY — triage a lead into a short draft note.
// No send, no publish, no spend, no delete. The output is a
// draft for Boss to read; a human (or a gated step) decides
// what happens next.
const lead = $input.first().json.payload || {};
const name = lead.business_name || 'Unknown business';
const need = lead.need || 'not stated';
return [{ json: {
  draft_note: `[DRAFT] Lead triage: ${name} — need: ${need}. ` +
    'Suggested next step: draft a reply, do not send.',
  business_name: name,
  need: need,
  draft_only: true
}}];
